// Garden holds a diagram and the children assigned to it.
type Garden struct {
	rows     [2]string
	children map[string]int // child name -> index of first cup
}

var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
